SELECT t.transaction_id, c.client_name, t.amount
FROM transactions t
JOIN clients c ON t.client_id = c.client_id;

SELECT c.client_name, t.transaction_id
FROM clients c
LEFT JOIN transactions t ON c.client_id = t.client_id;

SELECT transaction_id, amount,
CASE WHEN amount >= 50000 THEN 'large' ELSE 'small' END AS size_group
FROM transactions;

SELECT COUNT(*),
SUM(CASE WHEN status = 'declined' THEN 1 ELSE 0 END)
FROM transactions;

SELECT client_id, client_name
FROM clients
WHERE client_id IN (
  SELECT client_id FROM transactions WHERE status = 'declined'
);

SELECT transaction_id, client_id, amount,
ROW_NUMBER() OVER (
  PARTITION BY client_id ORDER BY transaction_date
) AS rn
FROM transactions;

SELECT transaction_id, client_id, amount,
SUM(amount) OVER (PARTITION BY client_id) AS client_total
FROM transactions;

SELECT transaction_id, client_id, amount,
LAG(amount) OVER (
  PARTITION BY client_id ORDER BY transaction_date
) AS prev_amount
FROM transactions;
